"""One offline neutral-geometry review with separate instance palette controls."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];c=json.loads((R/'elements/catalog.json').read_text());data=[]
for e in c['elements']:
 if e['id'].startswith(('house.','tree.')):data.append({'id':e['id'],'name':e['name'],'category':e['category'],'svg':(R/'elements'/e['file']).read_text()})
raw=json.dumps({'assets':data,'palettes':json.loads((R/'elements/palettes.json').read_text())},ensure_ascii=False).replace('<','\\u003c')
page='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>WIZAMAP · Hình gốc và màu riêng</title><style>body{margin:0;background:#eee4d1;color:#49362b;font:16px Georgia}header{padding:20px;background:#3b2925;color:#f3ead4}nav{position:sticky;top:0;padding:14px;background:#e6d8bc;display:flex;gap:15px;flex-wrap:wrap;z-index:2}select,button,input{font:inherit;padding:6px}main{padding:20px;display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:16px}article{border:1px solid #baa585;background:#faf2de;padding:12px}img{width:100%;height:260px;object-fit:contain}small{display:block;overflow-wrap:anywhere}[hidden]{display:none!important}</style><header><h1>WIZAMAP · Hình khối trước, màu sau</h1><p>18 base nhà trong ba nhóm; 12 cây có cấu trúc riêng và hai cây đặc biệt. Mặc định xem trung tính. Đổi màu không tạo asset mới.</p></header><nav><label>Màu <select id="palette"><option value="neutral">Trung tính — so hình</option><option value="warm">Áp màu ấm</option><option value="cool">Áp màu lạnh</option></select></label><label>Nhóm <select id="group"><option value="">Tất cả</option><option value="house.wood.">Nhà gỗ</option><option value="house.brick.">Nhà tường</option><option value="house.basic.">Khung basic</option><option value="tree.">Cây</option></select></label><label>Mái <input id="roof" type="color" value="#65705b"></label><label>Tán <input id="foliage" type="color" value="#91a477"></label><button id="reset">Về hình trung tính</button><span id="count"></span></nav><main id="grid"></main><script id="data" type="application/json">'''+raw+'''</script><script>
const {assets,palettes}=JSON.parse(document.querySelector('#data').textContent),q=s=>document.querySelector(s);let overrides={};
function instance(a){const doc=new DOMParser().parseFromString(a.svg,'image/svg+xml'),root=doc.documentElement;for(const [k,v]of Object.entries({...palettes[q('#palette').value],...overrides}))root.style.setProperty('--'+k,v);return new XMLSerializer().serializeToString(root)}
function draw(){q('#grid').replaceChildren();let n=0;for(const a of assets){if(!a.id.startsWith(q('#group').value))continue;n++;const article=document.createElement('article'),img=document.createElement('img'),title=document.createElement('p'),id=document.createElement('small'),b=document.createElement('button');img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(instance(a));img.alt=a.name;title.textContent=a.name;id.textContent=a.id;b.textContent='Tải SVG instance';b.onclick=()=>{const url=URL.createObjectURL(new Blob([instance(a)],{type:'image/svg+xml'})),link=document.createElement('a');link.href=url;link.download=a.id+'.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),2000)};article.dataset.id=a.id;article.append(img,title,id,b);q('#grid').append(article)}q('#count').textContent=n+' / '+assets.length}
q('#palette').onchange=()=>{overrides={};draw()};q('#group').onchange=draw;q('#roof').oninput=e=>{overrides.roof=e.target.value;draw()};q('#foliage').oninput=e=>{overrides.foliage=e.target.value;draw()};q('#reset').onclick=()=>{overrides={};q('#palette').value='neutral';draw()};draw();</script></html>'''
(R/'tools/scenery-review.html').write_text(page)
print(len(data),'scenery models in offline review')
